(4752833, 683963, 76335, '<td valign="top">A little too gritty for my tastes, but well composed and executed (no pun intended if that''s your subject''s fate).</td>', 'A little too gritty for my tastes, but well composed and executed (no pun intended if that''s your subject''s fate).', '2008-06-05 22:20:29.000000', NULL, 1),
