(4753175, 684581, 76430, '<td valign="top">It''s been done before but this is done better than the other two with the same title and theme, though not as close to the icon you are emulating <a href="//www.dpchallenge.com/image.php?IMAGE_ID=686154" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/75000-79999/76430/120/686154.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/75000-79999/76430/120/686154.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/75000-79999/76430/120/686154.gif"/></a>.  I think portrait mode may be better.</td>', 'It''s been done before but this is done better than the other two with the same title and theme, though not as close to the icon you are emulating .  I think portrait mode may be better.', '2008-06-06 01:50:05.000000', NULL, 1),
(4753180, 682335, 76430, '<td valign="top">Nice attempt, but the lighting on the eye is pretty harsh.  Is this using the on-camera flash?  Some side lighting with a bit of catch-light would really help this one.</td>', 'Nice attempt, but the lighting on the eye is pretty harsh.  Is this using the on-camera flash?  Some side lighting with a bit of catch-light would really help this one.', '2008-06-06 01:54:48.000000', NULL, 1),
(4753183, 683785, 76430, '<td valign="top">Too small a subject and too much negative space for me.  However it would work if it was darker and he was dressed and acting evil rather than like a casual businessman.</td>', 'Too small a subject and too much negative space for me.  However it would work if it was darker and he was dressed and acting evil rather than like a casual businessman.', '2008-06-06 01:56:19.000000', NULL, 1),
(4753224, 684492, 76430, '<td valign="top">Good shot, but too saturated on the blue to look plausible.  Move the apostrophe from "its" to "don''t".</td>', 'Good shot, but too saturated on the blue to look plausible.  Move the apostrophe from "its" to "don''t".', '2008-06-06 02:43:17.000000', NULL, 1),
(4753291, 684589, 23478, '<td valign="top">great detail, the eyes jump out and would benefit from being a bit sharper.</td>', 'great detail, the eyes jump out and would benefit from being a bit sharper.', '2008-06-06 03:26:54.000000', NULL, 1),
(4753760, 684673, 83649, '<td valign="top">µKJ</td>', 'µKJ', '2008-06-06 10:34:34.000000', NULL, 1),
(4753777, 684534, 8624, '<td valign="top">so playful and the color tones are amazing! one of my top 3!!!</td>', 'so playful and the color tones are amazing! one of my top 3!!!', '2008-06-06 10:43:43.000000', NULL, 1),
(4753779, 684684, 8624, '<td valign="top">such penetrating eyes! I love the face paint colors. Your post processing work is terrific.</td>', 'such penetrating eyes! I love the face paint colors. Your post processing work is terrific.', '2008-06-06 10:44:50.000000', NULL, 1),
(4753780, 684206, 8624, '<td valign="top">I love this shot - so many great textures between her silky hair, the lace of the mask, the soft sheen of the satin and the downy feather... and those sparkling eyes! wow!</td>', 'I love this shot - so many great textures between her silky hair, the lace of the mask, the soft sheen of the satin and the downy feather... and those sparkling eyes! wow!', '2008-06-06 10:46:04.000000', NULL, 1),
(4753784, 684528, 8624, '<td valign="top">really cool mask. love the tight crop</td>', 'really cool mask. love the tight crop', '2008-06-06 10:46:35.000000', NULL, 1),
(4753786, 682392, 8624, '<td valign="top">great lighting, cool mask.</td>', 'great lighting, cool mask.', '2008-06-06 10:46:53.000000', NULL, 1),
(4753790, 684691, 8624, '<td valign="top">really nicely captured. tight crop works well. I like the toning and the catchlight sparkles in her eyes.</td>', 'really nicely captured. tight crop works well. I like the toning and the catchlight sparkles in her eyes.', '2008-06-06 10:47:29.000000', NULL, 1),
(4753793, 684231, 8624, '<td valign="top">I love the glow around her created by the bokeh. great portrait</td>', 'I love the glow around her created by the bokeh. great portrait', '2008-06-06 10:48:16.000000', NULL, 1),
(4753795, 683341, 8624, '<td valign="top">very clever and well executed! great lighting. black and white works well here.</td>', 'very clever and well executed! great lighting. black and white works well here.', '2008-06-06 10:49:07.000000', NULL, 1),
(4753798, 684114, 8624, '<td valign="top">magical image. the bug eye mask really glows amid the cooler tones of the forest.</td>', 'magical image. the bug eye mask really glows amid the cooler tones of the forest.', '2008-06-06 10:49:37.000000', NULL, 1),
(4753803, 684523, 8624, '<td valign="top">gas masks are such great creepy props! I really like your composition here with the offset framing.</td>', 'gas masks are such great creepy props! I really like your composition here with the offset framing.', '2008-06-06 10:50:25.000000', NULL, 1),
(4753804, 684646, 8624, '<td valign="top">awesome lighting and toning! The backlight hair and shoulders add a cool glow and the face paint is great!</td>', 'awesome lighting and toning! The backlight hair and shoulders add a cool glow and the face paint is great!', '2008-06-06 10:51:05.000000', NULL, 1),
(4753807, 684583, 8624, '<td valign="top">love the pastel colors and sparkle!</td>', 'love the pastel colors and sparkle!', '2008-06-06 10:51:27.000000', NULL, 1),
(4753813, 684543, 8624, '<td valign="top">great mask and cool lipstick. I like how the ribbons flow with her hair.</td>', 'great mask and cool lipstick. I like how the ribbons flow with her hair.', '2008-06-06 10:52:25.000000', NULL, 1),
(4753814, 684643, 8624, '<td valign="top">great tones! that kid is gonna be scarred for life. {grin}</td>', 'great tones! that kid is gonna be scarred for life. {grin}', '2008-06-06 10:52:48.000000', NULL, 1),
(4753816, 684383, 8624, '<td valign="top">I like the pipes and dials behind the gas mask and the glow of the light through the goggles.</td>', 'I like the pipes and dials behind the gas mask and the glow of the light through the goggles.', '2008-06-06 10:53:24.000000', NULL, 1),
