(4753826, 684696, 8624, '<td valign="top">very fun. the stocking flattens the models features in a really interesting way - it almost looks like a 2 dimensional mask.</td>', 'very fun. the stocking flattens the models features in a really interesting way - it almost looks like a 2 dimensional mask.', '2008-06-06 10:55:37.000000', NULL, 1),
(4753827, 684447, 8624, '<td valign="top">scary! great makeup great lighting.</td>', 'scary! great makeup great lighting.', '2008-06-06 10:55:59.000000', NULL, 1),
(4753829, 684462, 8624, '<td valign="top">tones are a little flat. I''d like to see more pop in the whites of the duck and in her nose and cheeks.</td>', 'tones are a little flat. I''d like to see more pop in the whites of the duck and in her nose and cheeks.', '2008-06-06 10:56:36.000000', NULL, 1),
(4753831, 684581, 8624, '<td valign="top">funny! simple and clean, well done.</td>', 'funny! simple and clean, well done.', '2008-06-06 10:56:55.000000', NULL, 1),
