(4755264, 684678, 76430, '<td valign="top">Do you mean "Guardian"?  This looks like a miniature holding a dandylion in some grass, but overlooking the surroundings it really looks like a real person.</td>', 'Do you mean "Guardian"?  This looks like a miniature holding a dandylion in some grass, but overlooking the surroundings it really looks like a real person.', '2008-06-07 02:10:37.000000', NULL, 1),
(4755265, 683341, 76430, '<td valign="top">Wow, and excellent shot nicely set up and posed!  The only minor nitpick is the tie is too reflective.  I expect this to be among the top ones.  10 (my 5th 10 in over a year thanks to my new, more liberal grading scale).</td>', 'Wow, and excellent shot nicely set up and posed!  The only minor nitpick is the tie is too reflective.  I expect this to be among the top ones.  10 (my 5th 10 in over a year thanks to my new, more liberal grading scale).', '2008-06-07 02:11:53.000000', NULL, 1),
(4755266, 684528, 76430, '<td valign="top">Really beautiful mask, and nice composition.  The eyes really stand out.  10</td>', 'Really beautiful mask, and nice composition.  The eyes really stand out.  10', '2008-06-07 02:12:01.000000', NULL, 1),
(4755268, 684736, 76430, '<td valign="top">I''m really interested in seeing how you did this.  Is it multiple flashes in one exposure?  Disturbing horror movie shot.  Well done.  9</td>', 'I''m really interested in seeing how you did this.  Is it multiple flashes in one exposure?  Disturbing horror movie shot.  Well done.  9', '2008-06-07 02:12:54.000000', NULL, 1),
(4755269, 683954, 76430, '<td valign="top">Is that Bill Clinton?  Quite a statement.  Nice makeup job.  Good lighting.</td>', 'Is that Bill Clinton?  Quite a statement.  Nice makeup job.  Good lighting.', '2008-06-07 02:13:07.000000', NULL, 1),
(4755271, 683875, 76430, '<td valign="top">Excellent shot.  Very well composed and lit in an environment that I imagine is not set up for photography.</td>', 'Excellent shot.  Very well composed and lit in an environment that I imagine is not set up for photography.', '2008-06-07 02:14:03.000000', NULL, 1),
(4755275, 684504, 76430, '<td valign="top">Hi <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=16197" rel="nofollow" target="_blank">littlegett</a> (I think).  Nice lighting give the spooky look I see with this face a lot.  Very unique mask either very well homemade or unusual purchased one.</td>', 'Hi  littlegett (I think).  Nice lighting give the spooky look I see with this face a lot.  Very unique mask either very well homemade or unusual purchased one.', '2008-06-07 02:15:11.000000', NULL, 1),
(4755276, 684677, 76430, '<td valign="top">Unique mask and camoflage.  It looks like Peter Sellers.</td>', 'Unique mask and camoflage.  It looks like Peter Sellers.', '2008-06-07 02:15:15.000000', NULL, 1),
(4755278, 684585, 76430, '<td valign="top">Nice leading lines on the siding.</td>', 'Nice leading lines on the siding.', '2008-06-07 02:15:55.000000', NULL, 1),
(4755279, 683145, 76430, '<td valign="top">Technically not the best, but I''m giving you a 7 for creativity, the work involved in the costume and your expression.</td>', 'Technically not the best, but I''m giving you a 7 for creativity, the work involved in the costume and your expression.', '2008-06-07 02:16:02.000000', NULL, 1),
(4755280, 684606, 76430, '<td valign="top">Let the good times roll.  I like the colors and Mardi Gras theme.  Good DOF.  I have a couple ceramic masks like that but couldn''t come up with a good composition for this one.</td>', 'Let the good times roll.  I like the colors and Mardi Gras theme.  Good DOF.  I have a couple ceramic masks like that but couldn''t come up with a good composition for this one.', '2008-06-07 02:16:11.000000', NULL, 1),
(4755281, 684704, 76430, '<td valign="top">The skin is overexposed.  Otherwise it''s an excellent shot.  I love the eyes and lips.</td>', 'The skin is overexposed.  Otherwise it''s an excellent shot.  I love the eyes and lips.', '2008-06-07 02:17:39.000000', NULL, 1),
(4755282, 684554, 76430, '<td valign="top">Very interesting picture.  Is this IR?  I think this would be better in normal mode and save the IR for another scene IMHO.</td>', 'Very interesting picture.  Is this IR?  I think this would be better in normal mode and save the IR for another scene IMHO.', '2008-06-07 02:17:50.000000', NULL, 1),
(4755287, 684692, 76430, '<td valign="top">An extra point for the title!</td>', 'An extra point for the title!', '2008-06-07 02:22:56.000000', NULL, 1),
(4755293, 684583, 76430, '<td valign="top">I recognize your daughter, but don''t recall who this is.  The face kind of blends into the body or background, though that may be your intention, but otherwise nice shot.</td>', 'I recognize your daughter, but don''t recall who this is.  The face kind of blends into the body or background, though that may be your intention, but otherwise nice shot.', '2008-06-07 02:26:11.000000', NULL, 1),
